class Solution {
public:
    int partitionDisjoint(vector<int>& nums) {
        int n = nums.size();
        int maxLeft = nums[0];
        int maxSeen = nums[0];
        int partitionIdx = 0;
        for (int i = 1; i < n; i++) {
            if (nums[i] < maxLeft) {
                partitionIdx = i;
                maxLeft = maxSeen;
            } else {
                maxSeen = max(maxSeen, nums[i]);
            }
        }
        return partitionIdx + 1;
    }
};
